class TradePreCheckView(discord.ui.View):
    def __init__(self, requester_id: int, ticket_kwargs: dict[str, Any]) -> None:
        super().__init__(timeout=180)
        self.requester_id = requester_id
        self.ticket_kwargs = ticket_kwargs
        self.trade_method: str | None = None
        self.facility: str | None = None
        self.proof_method: str | None = None
        self.psn: str | None = None
        self.psn_timing: str | None = None
        self.server_link: str | None = None
        self.photo_timing: str | None = None
        self.photo_uploads: list[dict[str, Any]] = []
        self.opened_at = time.time()
        self.add_item(TradeMethodSelect(self.trade_method))
        self.add_item(PSNActionSelect(psn_dropdown_display(self)))
        self.add_item(ProofActionSelect(proof_dropdown_display(self)))

    def sync_facility_select(self) -> None:
        for item in list(self.children):
            if isinstance(item, GCTFFacilitySelect):
                self.remove_item(item)

        if self.trade_method == TRADE_METHOD_GCTF:
            self.add_item(GCTFFacilitySelect(self.facility))

    def sync_psn_select(self) -> None:
        for item in list(self.children):
            if isinstance(item, PSNActionSelect):
                self.remove_item(item)
        self.add_item(PSNActionSelect(psn_dropdown_display(self)))

    def sync_proof_select(self) -> None:
        for item in list(self.children):
            if isinstance(item, ProofActionSelect):
                self.remove_item(item)
        self.add_item(ProofActionSelect(proof_dropdown_display(self)))

    # Compatibility for older helper classes that are no longer added to the view.
    def sync_proof_detail_controls(self) -> None:
        self.sync_proof_select()

    @discord.ui.button(label="✅ Create trade ticket", style=discord.ButtonStyle.green, row=4)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if interaction.user.id != self.requester_id:
            await interaction.response.send_message("❌ This trade-check button was not opened for you.", ephemeral=True)
            return

        if not isinstance(interaction.channel, discord.TextChannel):
            await interaction.response.send_message("❌ This only works inside a server text channel.", ephemeral=True)
            return

        if self.trade_method not in {TRADE_METHOD_CARMEET, TRADE_METHOD_GCTF}:
            await interaction.response.send_message(
                "❌ Please choose **Carmeet** or **GCTF** from the dropdown first.",
                ephemeral=True,
            )
            return

        if not self.psn and self.psn_timing != PSN_TIMING_TICKET:
            await interaction.response.send_message(
                "❌ Please use the **PSN** dropdown and choose **Add PSN here** or **Inside ticket** before creating the trade ticket.",
                ephemeral=True,
            )
            return

        if self.trade_method == TRADE_METHOD_GCTF and not self.facility:
            await interaction.response.send_message(
                "❌ You selected **GCTF**, so please choose where your facility is before creating the ticket.",
                ephemeral=True,
            )
            return

        if self.proof_method not in {PROOF_METHOD_SERVER, PROOF_METHOD_PHOTOS}:
            await interaction.response.send_message(
                "❌ Please use the **Proof** dropdown and choose a Discord-invite or photo-proof option first.",
                ephemeral=True,
            )
            return

        if self.proof_method == PROOF_METHOD_SERVER:
            if self.server_link:
                clean_link = truncate_discord_text(str(self.server_link), 180, "Discord invite")
                proof_summary = f"Discord invite added in trade-check menu: {clean_link}"
            else:
                proof = await find_recent_trade_proof(interaction.channel, interaction.user.id, proof_kind=PROOF_METHOD_SERVER, after_timestamp=self.opened_at)
                if not proof.get("ok"):
                    await interaction.response.send_message(
                        "❌ You selected **Server** proof, so a Discord invite/link is required before I create the ticket.\n\n"
                        "Use the **Proof** dropdown, choose **Add Discord invite here**, paste the Discord invite, then press **Create trade ticket** again.",
                        ephemeral=True,
                    )
                    return
                proof_summary = str(proof.get("summary") or "Discord invite confirmed before ticket creation.")
        else:
            if self.photo_timing not in {PHOTO_TIMING_NOW, PHOTO_TIMING_TICKET}:
                await interaction.response.send_message(
                    "❌ You selected **Photos** proof, so please choose **Add photos here** or **Photos inside ticket** from the Proof dropdown first.",
                    ephemeral=True,
                )
                return

            proof = await find_recent_trade_proof(interaction.channel, interaction.user.id, proof_kind=PROOF_METHOD_PHOTOS, after_timestamp=self.opened_at)
            if self.photo_uploads:
                upload_lines = []
                for item in self.photo_uploads[:10]:
                    filename = truncate_discord_text(item.get("filename"), 80, "photo")
                    url = truncate_discord_text(item.get("url"), 220, "")
                    upload_lines.append(f"- {filename}: {url}" if url else f"- {filename}")
                proof_summary = "Photo proof uploaded in trade-check menu:\n" + "\n".join(upload_lines)
            elif self.photo_timing == PHOTO_TIMING_NOW:
                if not proof.get("ok"):
                    await interaction.response.send_message(
                        "❌ You chose **Add photos here**, but I could not see image proof yet.\n\n"
                        "Use the **Proof** dropdown and choose **Add photos here** again if your bot version supports it, or use Discord's **+ attachment button** in this channel.\n"
                        "Then press **Create trade ticket** again, or change the proof option to **Photos inside ticket**.",
                        ephemeral=True,
                    )
                    return
                proof_summary = str(proof.get("summary") or "Photo proof was attached before ticket creation.")
            else:
                if proof.get("ok"):
                    proof_summary = str(proof.get("summary") or "Photo proof was attached before ticket creation.")
                else:
                    proof_summary = "Photo proof selected. User chose to attach photos inside this ticket after it is created."

        if interaction.guild is None:
            await interaction.response.send_message("❌ This only works inside a server.", ephemeral=True)
            return

        await interaction.response.defer(ephemeral=True, thinking=True)
        sentinel_gate = await sentinel_trade_gate(
            interaction.guild,
            interaction.user,
            trade_method=str(self.trade_method),
            psn=self.psn,
            facility=self.facility,
            server_link=self.server_link,
            photo_uploads=self.photo_uploads,
        )
        if sentinel_gate.get("requires_challenge"):
            challenge = sentinel_gate.get("challenge") or {}
            code = str(challenge.get("challenge_code") or "XSI verification code")
            tailored = str((sentinel_gate.get("ai_decision") or {}).get("user_message") or "Fresh proof is required before this trade ticket can open.")
            reasons = "\n".join(f"• {item}" for item in (sentinel_gate.get("signals") or [])[:4])
            await interaction.followup.send(
                f"🛡️ **XSI Sentinel verification required**\n\n"
                f"{sanitize_ai_text(tailored, 700)}\n\n"
                f"Upload a **new image** in this channel visibly showing `{code}` and include the code in the message. "
                f"Then press the trade-ticket button again. The code expires in {SENTINEL_CHALLENGE_MINUTES} minutes."
                + (f"\n\nWhy extra verification was requested:\n{reasons}" if reasons else ""),
                ephemeral=True,
                allowed_mentions=discord.AllowedMentions.none(),
            )
            return

        ticket_kwargs = dict(self.ticket_kwargs)
        psn_summary = self.psn if self.psn else "User chose to provide PSN inside the ticket."
        trade_lines = [
            f"✅ {proof_summary}",
            f"Trade option: {self.trade_method}",
            f"PSN: {psn_summary}",
            f"Proof method: {self.proof_method}",
        ]
        if self.psn_timing:
            trade_lines.append(f"PSN option: {self.psn_timing}")
        if self.proof_method == PROOF_METHOD_PHOTOS and self.photo_timing:
            trade_lines.append(f"Photo option: {self.photo_timing}")
        if self.trade_method == TRADE_METHOD_GCTF and self.facility:
            trade_lines.append(f"Facility: {self.facility}")
        trade_lines.append(f"Sentinel risk at intake: {sentinel_gate.get('risk', 0)}/100")
        if sentinel_gate.get("verified"):
            trade_lines.append("Sentinel fresh-proof challenge: verified")
        if sentinel_gate.get("signals"):
            trade_lines.append("Sentinel review signals: " + "; ".join(str(item) for item in sentinel_gate.get("signals", [])[:4]))

        current_reason = str(ticket_kwargs.get("ticket_reason") or "").strip()
        trade_summary = "\n".join(trade_lines)
        ticket_kwargs["ticket_reason"] = (
            f"{current_reason}\n\n{trade_summary}" if current_reason else trade_summary
        )

        for item in self.children:
            item.disabled = True

        created_channel = await create_ticket_channel(interaction, **ticket_kwargs)
        if created_channel is not None:
            await sentinel_store_trade_intake(
                created_channel,
                interaction.user,
                psn=self.psn,
                server_link=self.server_link,
                photo_uploads=self.photo_uploads,
                risk=int(sentinel_gate.get("risk", 0)),
                signals=[str(item) for item in sentinel_gate.get("signals", [])],
            )

class TicketPanelButton(discord.ui.Button):
    def __init__(self, index: int, config: dict[str, Any] | None = None) -> None:
        self.index = index
        config = config or {"label": f"Ticket {index}", "style": "green", "auto_messages": True}
        super().__init__(
            label=normalize_ticket_button_label(config.get("label")) or f"Ticket {index}",
            emoji=discord_button_emoji(config.get("emoji")),
            style=ticket_button_style(str(config.get("style") or "green")),
            custom_id=f"{TICKET_PANEL_CUSTOM_ID_PREFIX}{index}",
            row=(index - 1) // 5,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        if interaction.guild is None:
            await interaction.response.send_message("❌ This only works inside a server.", ephemeral=True)
            return

        config = get_ticket_button_config_for_index(interaction.guild.id, self.index)
        if config is None:
            await interaction.response.send_message(
                "❌ That ticket button is not configured anymore. Ask an admin to refresh the ticket panel.",
                ephemeral=True,
            )
            return

        ticket_kwargs = {
            "auto_messages": bool(config.get("auto_messages", True)),
            "ticket_type": str(config.get("label") or "Ticket"),
            "button_index": self.index,
            "category_id": _safe_int(config.get("category_id"), 0) or None,
            "ticket_reason": str(config.get("reason") or "").strip() or None,
        }

        if ticket_button_requires_trade_proof(config):
            view = TradePreCheckView(interaction.user.id, ticket_kwargs)
            await interaction.response.send_message(
                trade_precheck_message(view),
                view=view,
                ephemeral=True,
            )
            return

        await create_ticket_channel(interaction, **ticket_kwargs)


