@bot.event
async def on_message(message: discord.Message) -> None:
    if message.author.bot:
        return
    if message.guild is None or not isinstance(message.author, discord.Member):
        return

    member = message.author

    # Sentinel runs before auto-replies or trade forwarding so blocked content is
    # never copied, amplified, or answered by another automation.
    sentinel_blocked = await sentinel_process_message(message)
    if sentinel_blocked:
        return

    colour_handled = await maybe_handle_colour_channel(message)
    await append_ticket_record_message(message)
    await maybe_dm_ticket_owner(message)
    await maybe_send_unavailable_ticket_reply(message)
    await maybe_handle_smart_message(message)
    await maybe_handle_trade_auto(message)

    if is_staff_or_mod(member):
        if not colour_handled:
            await maybe_handle_ai_reply(message)
        await bot.process_commands(message)
        return

    content = message.content or ""
    offence = detect_offence(content)
    if offence is None and is_spam(message.guild.id, message.channel.id, member.id, content):
        offence = "Spam / repeated messages"

    if offence is None:
        await maybe_ai_moderation_watch(message)
        if not colour_handled:
            await maybe_handle_ai_reply(message)

    if offence is not None:
        warning_count = await add_warning(message.guild.id, member.id)
        try:
            await message.delete()
        except discord.Forbidden:
            await message.channel.send("❌ I need Manage Messages permission.")
        except discord.HTTPException:
            pass

        if warning_count >= MAX_WARNINGS:
            punishment = "Banned" if PUNISHMENT_ON_MAX_WARNINGS.lower() == "ban" else "Kicked"
            await send_wall_log(member, offence, punishment, content, warning_count)
            try:
                await punish_if_needed(message.guild, message.channel, member, offence, warning_count)
            except discord.Forbidden:
                await message.channel.send(f"❌ I do not have permission to punish {member.mention}.")
            except discord.HTTPException as exc:
                log.exception("Punishment failed: %s", exc)
                await message.channel.send("❌ Something went wrong while punishing.")
            return

        await send_wall_log(member, offence, "Warning", content, warning_count)
        await message.channel.send(
            f"⚠️ {member.mention}, warning {warning_count}/{MAX_WARNINGS} — {offence}.\nYour message was deleted."
        )
        return

    await bot.process_commands(message)


@bot.event
async def on_raw_message_edit(payload: discord.RawMessageUpdateEvent) -> None:
    """Forward DMO posts when the user edits a picture post to add the DMO trigger.

    Discord's normal on_message event only runs when the message is first sent.
    This raw edit event fetches the edited message, so the bot can see the final
    text and attachments after a mobile edit. Duplicate protection in the DMO
    forwarder prevents the same source message being forwarded twice.
    """
    if payload.guild_id is None:
        return

    guild = bot.get_guild(payload.guild_id)
    if guild is None:
        return

    channel = bot.get_channel(payload.channel_id)
    if channel is None:
        try:
            channel = await bot.fetch_channel(payload.channel_id)
        except discord.HTTPException:
            return

    if not isinstance(channel, (discord.TextChannel, discord.Thread)):
        return

    try:
        message = await channel.fetch_message(payload.message_id)
    except discord.HTTPException:
        return

    if message.guild is None or message.guild.id != guild.id:
        return

    sentinel_blocked = await sentinel_process_message(message)
    if sentinel_blocked:
        return
    await maybe_handle_trade_auto_message_edit(message)


